    80	
    81	/**
    82	 * Compare expected (from disk) vs applied (from DB). Returns a discriminated
    83	 * union the caller can branch on, instead of throwing — keeps tests cheap.
    84	 */
    85	export function compareSchemaVersions(
    86	  expected: string | null,
    87	  applied: string | null
    88	): SchemaVersionOk | SchemaVersionMismatch {
    89	  if (expected === null) return { kind: 'ok', expected, applied };
    90	  if (applied !== null && applied >= expected) {
    91	    return { kind: 'ok', expected, applied };
    92	  }
    93	  return { kind: 'mismatch', expected, applied };
    94	}
    95	
    96	/**
    97	 * Boot-time assertion: throws if the database is behind the image's
    98	 * migrations directory. Call once during server startup, before opening the
    99	 * HTTP listener.
   100	 *
   101	 * Fails closed in production: if `migrationsDir` can't be listed (bad path,
   102	 * missing copy in the image, wrong volume mount), `NODE_ENV=production`
   103	 * treats that as a deployment defect and throws. In dev a missing/empty
   104	 * directory degrades to a warning — so `bun run dev` from a worktree that
   105	 * doesn't have `db/` checked out still boots.
   106	 */
   107	export async function assertSchemaUpToDate(
   108	  sql: DbClient,
   109	  options: { migrationsDir: string }
   110	): Promise<void> {
   111	  const expected = readExpectedSchemaVersion(options.migrationsDir);
   112	
   113	  if (expected === null && process.env.NODE_ENV === 'production') {
   114	    const msg =
   115	      `[schema-check] migrations directory ${options.migrationsDir} is empty or unreadable in a ` +
   116	      `production build — the image is missing db/migrations. Refusing to start.`;
   117	    logger.error({ migrationsDir: options.migrationsDir }, msg);
   118	    throw new Error(msg);
   119	  }
   120	
   121	  const applied = await readAppliedSchemaVersion(sql);
   122	  const result = compareSchemaVersions(expected, applied);
   123	
   124	  if (result.kind === 'mismatch') {
   125	    const msg =
   126	      `[schema-check] database is behind the image. Expected migration ${result.expected} ` +
   127	      `to be applied, but the highest applied version is ${result.applied ?? '(none)'}. ` +
   128	      `Run \`dbmate up\` against this database before rolling out this image.`;
   129	    logger.error(
   130	      { expected: result.expected, applied: result.applied, migrationsDir: options.migrationsDir },
   131	      msg
   132	    );
   133	    throw new Error(msg);
   134	  }
   135	
   136	  logger.info(
   137	    { expected: result.expected, applied: result.applied },
   138	    '[schema-check] schema version up to date'
   139	  );
   140	}

